def normalize_cve_id(vuln_data):
    """
    Return a CVE identifier for the vulnerability if present.

    Trivy may emit non-CVE IDs (e.g., GHSA-*). This function enforces CVE formatting
    and attempts to recover a CVE from other fields/URLs when possible.

    Returns:
        A string like 'CVE-YYYY-NNNN...' or None if no CVE can be determined.
    """
    import re

    def first_cve_in_text(text):
        if not text:
            return None
        m = re.search(r"CVE-\d{4}-\d{4,}", str(text), flags=re.IGNORECASE)
        return m.group(0).upper() if m else None

    vid = vuln_data.get('VulnerabilityID')
    cve = first_cve_in_text(vid)
    if cve:
        return cve

    # Common Trivy fields that may contain a CVE (URLs often include it)
    for key in ("PrimaryURL", "Title"):
        cve = first_cve_in_text(vuln_data.get(key))
        if cve:
            return cve

    # References may include NVD/MITRE URLs
    for ref in (vuln_data.get('References') or []):
        cve = first_cve_in_text(ref)
        if cve:
            return cve

    return None


def get_cvss_score(vuln_data):
    """Extract CVSS score with source priority."""
    cvss = vuln_data.get('CVSS', {})
    for source in ['nvd', 'ghsa', 'redhat']:
        if source in cvss:
            score = cvss[source].get('V3Score')
            if score is not None:
                return score
    return 'N/A'
